 add(15,3,'JWT interno sin permiso de portal','Tabla de decisión',{'perfil':'qa_cajero'},'HTTP 403; cuerpo sin datos de cliente ni de cuentas. qa_cajero no posee portal.mi_banco.ver.',I+'/api/portal/resumen','GET',pre='qa_cajero activo con rol CAJERO, sin permiso portal.mi_banco.ver.',steps=[f'Autenticar qa_cajero con POST {login} y cuerpo {cajero}; guardar token.',"En psql-QA confirmar que el permiso no está asignado: SELECT count(*) FROM seguridad.permisos p WHERE p.codigo='portal.mi_banco.ver' AND p.id IN (SELECT rp.permiso_id FROM seguridad.roles_permisos rp JOIN seguridad.usuarios_roles ur ON ur.rol_id=rp.rol_id JOIN seguridad.usuarios u ON u.id=ur.usuario_id WHERE u.username='qa_cajero'); esperar 0.",f'Enviar GET {I}/api/portal/resumen con Authorization: Bearer <token>.','Verificar HTTP 403 y ausencia de las claves cliente y cuentas.'])
