 i1=add(22,1,'Preflight POST con encabezados desde origen permitido','Partición de equivalencia',{'Origin':'http://localhost:13000','Access-Control-Request-Method':'POST','Access-Control-Request-Headers':'content-type,authorization'},'HTTP 204; Access-Control-Allow-Origin=http://localhost:13000; Access-Control-Allow-Methods=POST; Access-Control-Allow-Headers=content-type,authorization.',cors,'OPTIONS',pre='CORS_ALLOWED_ORIGINS del entorno QA = http://localhost:13000.',steps=cors_steps('http://localhost:13000',True))
