 i3=add(22,2,'Origen que contiene el permitido como prefijo','Partición de equivalencia',{'Origin':'http://localhost:13000.evil.invalid','Access-Control-Request-Method':'POST','Access-Control-Request-Headers':'content-type,authorization'},'HTTP 204; sin Access-Control-Allow-Origin, Access-Control-Allow-Methods ni Access-Control-Allow-Headers; la comparación de origen es exacta, no por prefijo.',cors,'OPTIONS',pre='CORS_ALLOWED_ORIGINS del entorno QA = http://localhost:13000; dominio .invalid reservado, sin resolución DNS.',steps=cors_steps('http://localhost:13000.evil.invalid',False))
